{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "GSK1322322, a high-transfer analogue, showed 77% absolute oral bioavailability in healthy volunteers after a fed dose, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Betaxolol, a high-transfer analogue, showed absolute oral bioavailability of 87.5 ± 7.9%, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "SL 75212, a high-transfer analogue, showed absolute bioavailability of 89 ± 5%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Veralipride, a high-transfer analogue, showed absolute oral bioavailability of 78.63 ± 20.23%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "AZD0837, a high-transfer analogue, showed absolute oral bioavailability of 22–55%, with the lower bound at the threshold and mean clearly above 20%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Omeprazole, a high-transfer analogue, showed mean oral bioavailability of 56%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Abecarnil, a high-transfer analogue, showed oral bioavailability of approximately 60%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Encainide, a high-transfer analogue, showed mean oral bioavailability of 41.9%, supporting high bioavailability despite wide interindividual variability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability above 20%, most well above 50%, and the physicochemical prior is favorable; therefore the query molecule is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "First-pass metabolism and transporter-mediated efflux for the query are not experimentally characterized.",
    "Encainide data show wide interindividual variability, indicating possible first-pass liability, but the mean remains above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

